def norm(mm):
    rows=[r for r in mm if '#' in r]
    if not rows: return ()
    left=min(r.index('#') for r in rows)
    right=min(len(r)-1-r.rindex('#') for r in rows)
    return tuple(r[left:len(r)-right] for r in rows)
